t.script:
                document.addEventListener('DOMContentLoaded', function () {
                    var container = document.getElementById('productLinesContainer');
                    var btnAdd = document.getElementById('btnAddProduct');
                    var datalist = document.getElementById('productList');

                    function formatCurrency(amount) {
                        var num = parseFloat(amount) || 0;
                        return 'Rp. ' + Math.round(num).toLocaleString('en-US');
                    }

                    function calculateGrandTotal() {
                        var grandTotalDisplay = document.getElementById('grandTotalDisplay');
                        if (!grandTotalDisplay || !container) return;

                        var lines = container.querySelectorAll('.product-line-item');
                        var total = 0;

                        lines.forEach(function (line) {
                            var priceInput = line.querySelector('.price-unit-input');
                            var qtyInput = line.querySelector('.quantity-input');

                            var price = parseFloat(priceInput ? priceInput.value : 0) || 0;
                            var qty = parseFloat(qtyInput ? qtyInput.value : 0) || 0;

                            total += price * qty;
                        });

                        grandTotalDisplay.textContent = 'Rp ' + Math.round(total).toLocaleString('id-ID');
                    }

                    function updateProductData(element) {
                        var searchInput = element.querySelector('.product-search-input');
                        var displayDiv = element.querySelector('.selected-product-display');
                        var hiddenIdInput = element.querySelector('.product-id-input');
                        var barcodeInput = element.querySelector('.barcode-input');
                        var priceInput = element.querySelector('.price-unit-input');
                        var priceDisplay = element.querySelector('.price-unit-display');

                        if (!searchInput || !hiddenIdInput || !datalist) return;

                        var val = searchInput.value.trim().toLowerCase();
                        if (!val) {
                            hiddenIdInput.value = '';
                            if (barcodeInput) barcodeInput.value = '';
                            if (priceInput) priceInput.value = '';
                            if (priceDisplay) priceDisplay.value = '';
                            if (displayDiv) {
                                displayDiv.style.display = 'none';
                                displayDiv.textContent = '';
                            }
                            searchInput.style.display = 'block';
                            searchInput.required = true;
                            calculateGrandTotal();
                            return;
                        }

                        var options = datalist.options;
                        var matchedOpt = null;

                        for (var i = 0; i < options.length; i++) {
                            var opt = options[i];
                            var optVal = (opt.value || '').toLowerCase();
                            var optName = (opt.getAttribute('data-name') || '').toLowerCase();
                            var optBarcode = (opt.getAttribute('data-barcode') || '').toLowerCase();
                            var optCode = (opt.getAttribute('data-code') || '').toLowerCase();
                            var optDisplay = (opt.getAttribute('data-display') || '').toLowerCase();

                            if (val === optVal || val === optName || (optBarcode && val === optBarcode) || (optCode && val === optCode) || val === optDisplay) {
                                matchedOpt = opt;
                                break;
                            }
                        }

                        if (matchedOpt) {
                            var prodName = matchedOpt.getAttribute('data-name') || matchedOpt.value;
                            var rawPrice = parseFloat(matchedOpt.getAttribute('data-price') || '0') || 0;
                            hiddenIdInput.value = matchedOpt.getAttribute('data-id') || '';
                            if (barcodeInput) barcodeInput.value = matchedOpt.getAttribute('data-barcode') || '';
                            if (priceInput) priceInput.value = rawPrice;
                            if (priceDisplay) priceDisplay.value = formatCurrency(rawPrice);
                            searchInput.value = prodName;

                            if (displayDiv) {
                                displayDiv.textContent = prodName;
                                displayDiv.style.display = 'block';
                                searchInput.style.display = 'none';
                                searchInput.required = false;
                            }
                        } else {
                            hiddenIdInput.value = '';
                            if (barcodeInput) barcodeInput.value = '';
                            if (priceInput) priceInput.value = '';
                            if (priceDisplay) priceDisplay.value = '';
                            if (displayDiv) {
                                displayDiv.style.display = 'none';
                                displayDiv.textContent = '';
                            }
                            searchInput.style.display = 'block';
                            searchInput.required = true;
                        }

                        calculateGrandTotal();
                    }

                    function bindProductSelectEvent(element) {
                        var searchInput = element.querySelector('.product-search-input');
                        var displayDiv = element.querySelector('.selected-product-display');

                        if (displayDiv && searchInput) {
                            displayDiv.addEventListener('click', function () {
                                displayDiv.style.display = 'none';
                                searchInput.style.display = 'block';
                                searchInput.required = true;
                                searchInput.focus();
                                searchInput.select();
                            });
                        }

                        if (searchInput) {
                            searchInput.addEventListener('input', function () {
                                updateProductData(element);
                            });
                            searchInput.addEventListener('change', function () {
                                updateProductData(element);
                            });
                        }

                        var qtyInput = element.querySelector('.quantity-input');
                        if (qtyInput) {
                            qtyInput.addEventListener('input', calculateGrandTotal);
                            qtyInput.addEventListener('change', calculateGrandTotal);
                        }

                        var priceInput = element.querySelector('.price-unit-input');
                        if (priceInput) {
                            priceInput.addEventListener('input', calculateGrandTotal);
                            priceInput.addEventListener('change', calculateGrandTotal);
                        }

                        var btnRemove = element.querySelector('.btn-remove-line');
                        if (btnRemove) {
                            btnRemove.addEventListener('click', function () {
                                var lines = container.querySelectorAll('.product-line-item');
                                if (lines.length > 1) {
                                    element.remove();
                                    calculateGrandTotal();
                                } else {
                                    alert('Minimal harus ada 1 menu pesanan.');
                                }
                            });
                        }
                    }

                    var initialLine = container.querySelector('.product-line-item');
                    if (initialLine) {
                        bindProductSelectEvent(initialLine);
                    }

                    if (btnAdd) {
                        btnAdd.addEventListener('click', function () {
                            var firstLine = container.querySelector('.product-line-item');
                            if (firstLine) {
                                var clone = firstLine.cloneNode(true);
                                var cloneSearchInput = clone.querySelector('.product-search-input');
                                var cloneDisplayDiv = clone.querySelector('.selected-product-display');
                                if (cloneSearchInput) {
                                    cloneSearchInput.value = '';
                                    cloneSearchInput.style.display = 'block';
                                    cloneSearchInput.required = true;
                                }
                                if (cloneDisplayDiv) {
                                    cloneDisplayDiv.style.display = 'none';
                                    cloneDisplayDiv.textContent = '';
                                }
                                clone.querySelector('.product-id-input').value = '';
                                if (clone.querySelector('.barcode-input')) clone.querySelector('.barcode-input').value = '';
                                if (clone.querySelector('.price-unit-input')) clone.querySelector('.price-unit-input').value = '';
                                if (clone.querySelector('.price-unit-display')) clone.querySelector('.price-unit-display').value = '';
                                clone.querySelector('.quantity-input').value = '1';
                                container.appendChild(clone);
                                bindProductSelectEvent(clone);
                                calculateGrandTotal();
                            }
                        });
                    }

                    var btnShowSummary = document.getElementById('btnShowSummary');
                    var orderSummaryModal = document.getElementById('orderSummaryModal');

                    function populateAndShowSummary() {
                        var customerNameInput = document.getElementById('customer_name');
                        var tableNumberInput = document.getElementById('table_number');

                        var summaryCustomerName = document.getElementById('summaryCustomerName');
                        var summaryTableNumber = document.getElementById('summaryTableNumber');
                        var summaryItemsList = document.getElementById('summaryItemsList');
                        var summaryTotalTypes = document.getElementById('summaryTotalTypes');
                        var summaryTotalQty = document.getElementById('summaryTotalQty');
                        var summaryGrandTotal = document.getElementById('summaryGrandTotal');

                        if (summaryCustomerName) summaryCustomerName.textContent = (customerNameInput && customerNameInput.value.trim()) ? customerNameInput.value.trim() : '-';
                        if (summaryTableNumber) summaryTableNumber.textContent = (tableNumberInput && tableNumberInput.value.trim()) ? tableNumberInput.value.trim() : '-';

                        if (!container || !summaryItemsList) return;

                        summaryItemsList.innerHTML = '';
                        var lines = container.querySelectorAll('.product-line-item');

                        var totalTypes = 0;
                        var totalQty = 0;
                        var grandTotal = 0;

                        lines.forEach(function (line, index) {
                            var searchInput = line.querySelector('.product-search-input');
                            var priceInput = line.querySelector('.price-unit-input');
                            var qtyInput = line.querySelector('.quantity-input');
                            var hiddenIdInput = line.querySelector('.product-id-input');

                            var prodName = (searchInput ? searchInput.value.trim() : '') || 'Menu ' + (index + 1);
                            var price = parseFloat(priceInput ? priceInput.value : 0) || 0;
                            var qty = parseFloat(qtyInput ? qtyInput.value : 0) || 0;
                            var subtotal = price * qty;

                            if (hiddenIdInput && hiddenIdInput.value) {
                                totalTypes++;
                                totalQty += qty;
                                grandTotal += subtotal;

                                var itemDiv = document.createElement('div');
                                itemDiv.className = 'list-group-item d-flex justify-content-between align-items-center p-2';
                                itemDiv.innerHTML = '
' +
                                    '' + prodName + '
' +
                                    '' + formatCurrency(price) + ' x ' + qty + '' +
                                    '' +
                                    '' + formatCurrency(subtotal) + '';
                                summaryItemsList.appendChild(itemDiv);
                            }
                        });

                        if (totalTypes === 0) {
                            summaryItemsList.innerHTML = '
Belum ada menu yang dipilih.';
                        }

                        if (summaryTotalTypes) summaryTotalTypes.textContent = totalTypes + ' menu';
                        if (summaryTotalQty) summaryTotalQty.textContent = totalQty + ' porsi';
                        if (summaryGrandTotal) summaryGrandTotal.textContent = formatCurrency(grandTotal);

                        if (typeof $ !== 'undefined' && $.fn && $.fn.modal) {
                            $('#orderSummaryModal').modal('show');
                        } else if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
                            var modalObj = bootstrap.Modal.getInstance(orderSummaryModal) || new bootstrap.Modal(orderSummaryModal);
                            modalObj.show();
                        } else if (orderSummaryModal) {
                            orderSummaryModal.classList.add('show');
                            orderSummaryModal.style.display = 'block';
                        }
                    }

                    if (btnShowSummary) {
                        btnShowSummary.addEventListener('click', populateAndShowSummary);
                    }

                    calculateGrandTotal();
                });
